CREATE TABLE requirement_evidence_bindings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requirement_id uuid NOT NULL REFERENCES institutional_source_requirements(id) ON DELETE CASCADE, evidence_id uuid REFERENCES asset_evidence(id) ON DELETE SET NULL, project_id uuid NOT NULL, status text NOT NULL DEFAULT 'missing', confidence numeric(6,2), notes text, checked_at timestamptz NOT NULL DEFAULT now(), UNIQUE(requirement_id,project_id));